  if (name === 'COUNT') return num(vals.filter((v) => v.k === 'n').length)
  const nums = []
  for (const v of vals) {
    const x = asNum(v)
    if (x.k === 'e') return x
    nums.push(x.v)
  }
  switch (name) {
    case 'ABS':
      if (nums.length !== 1) return err('#ERR!')
      return num(Math.abs(nums[0]))
    case 'SUM': return finite(nums.reduce((a, b) => a + b, 0))
    case 'MIN': return num(Math.min(...nums))
    case 'MAX': return num(Math.max(...nums))
    case 'AVG': return finite(nums.reduce((a, b) => a + b, 0) / nums.length)
  }
  return err('#ERR!')
}

function show(v) {
  switch (v.k) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

const out = []
for (const c of [...cells.values()].sort(byPos)) {
  out.push(`${c.key}=${show(cellValue(c.key))}\n`)
}
process.stdout.write(out.join(''))
