#!/usr/bin/env node
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const ERRS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const err = (e) => ({ k: 'e', v: e })
const num = (n) => ({ k: 'n', v: n })
const ADDR = /^([A-Za-z]{1,2})([0-9]{1,3})$/

function parseAddr(w) {
  const m = ADDR.exec(w)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const letters = m[1].toUpperCase()
  let col = 0
  for (const ch of letters) col = col * 26 + ch.charCodeAt(0) - 64
  return { col, row, key: letters + row }
}
const keyOf = (col, row) => {
  let s = ''
  let c = col
  while (c > 0) {
    s = String.fromCharCode(65 + ((c - 1) % 26)) + s
    c = Math.floor((c - 1) / 26)
  }
  return s + row
}

// ---------- parsing the sheet ----------
const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(s)
  const addrTok = m[1]
  const a = parseAddr(addrTok)
  if (!a) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${addrTok}\n`)
    process.exit(2)
  }
  if (cells.has(a.key)) {
    process.stderr.write(`error: line ${i + 1}: cell ${a.key} is declared twice\n`)
    process.exit(2)
  }
  cells.set(a.key, { ...a, content: m[2] })
}

// ---------- formula parsing ----------
function tokenize(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const c = src[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) {
      toks.push({ t: 'word', v: m[0] }); i += m[0].length
    } else if ((m = /^(<>|<=|>=|[<>=^*\/+\-(),:])/.exec(src.slice(i)))) {
      toks.push({ t: 'op', v: m[0] }); i += m[0].length
    } else return null
  }
  return toks
}

function parseFormula(src) {
  const toks = tokenize(src)
  if (!toks) return null
  let p = 0
  let bad = false
  const fail = () => { throw new Error('parse') }
  const isOp = (v, o = 0) => toks[p + o] && toks[p + o].t === 'op' && toks[p + o].v === v
  const CMP = ['=', '<>', '<', '<=', '>', '>=']
  function cmp() {
    let l = add()
    while (toks[p] && toks[p].t === 'op' && CMP.includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { t: 'neg', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const tk = toks[p]
    if (!tk) fail()
    if (tk.t === 'num') { p++; return { t: 'num', v: tk.v } }
    if (tk.t === 'op') {
      if (tk.v !== '(') fail()
      p++
      const e = cmp()
      if (!isOp(')')) fail()
      p++
      return e
    }
    p++
    const name = tk.v.toUpperCase()
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) p++
      else {
        for (;;) {
          args.push(arg())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          fail()
        }
      }
      return { t: 'call', name, args }
    }
    if (isOp(':')) {
      p++
      const w = toks[p]
      if (!w || w.t !== 'word') fail()
      p++
      bad = true
      return { t: 'range', a: tk.v, b: w.v }
    }
    if (name === 'TRUE') return { t: 'bool', v: true }
    if (name === 'FALSE') return { t: 'bool', v: false }
    return { t: 'ref', w: tk.v }
  }
  function arg() {
    if (toks[p] && toks[p].t === 'word' && isOp(':', 1) && toks[p + 2] && toks[p + 2].t === 'word' &&
      (isOp(',', 3) || isOp(')', 3))) {
      const r = { t: 'range', a: toks[p].v, b: toks[p + 2].v }
      p += 3
      return r
    }
    return cmp()
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    return { e, bad }
  } catch {
    return null
  }
}

const ARITY = { SUM: [1, Infinity], MIN: [1, Infinity], MAX: [1, Infinity], COUNT: [1, Infinity], AVG: [1, Infinity], ABS: [1, 1], IF: [3, 3] }

function staticBad(n) {
  switch (n.t) {
    case 'bin': return staticBad(n.l) || staticBad(n.r)
    case 'neg': return staticBad(n.e)
    case 'call': {
      const ar = ARITY[n.name]
      if (ar && (n.args.length < ar[0] || n.args.length > ar[1])) return true
      return n.args.some((a) => (a.t === 'range' ? false : staticBad(a)))
    }
    case 'range': return true
    default: return false
  }
}

function collectDeps(n, out) {
  switch (n.t) {
    case 'bin': collectDeps(n.l, out); collectDeps(n.r, out); break
    case 'neg': collectDeps(n.e, out); break
    case 'call': n.args.forEach((a) => collectDeps(a, out)); break
    case 'ref': { const a = parseAddr(n.w); if (a) out.set(a.key, a); break }
    case 'range': {
      const a = parseAddr(n.a), b = parseAddr(n.b)
      if (a && b) {
        for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
          for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++)
            out.set(keyOf(c, r), { col: c, row: r, key: keyOf(c, r) })
      }
      break
    }
  }
}

for (const c of cells.values()) {
  if (c.content[0] === '=') {
    c.ast = parseFormula(c.content.slice(1))
    if (c.ast) c.ast.isBad = c.ast.bad || staticBad(c.ast.e)
  }
}

const byPos = (x, y) => x.col - y.col || x.row - y.row

if (mode === 'deps') {
  const out = []
  for (const c of [...cells.values()].sort(byPos)) {
    const d = new Map()
    if (c.ast) collectDeps(c.ast.e, d)
    const list = [...d.values()].sort(byPos)
    out.push(`${c.key}:` + list.map((x) => ' ' + x.key).join(''))
  }
  process.stdout.write(out.map((l) => l + '\n').join(''))
  process.exit(0)
}

// ---------- evaluation ----------
const memo = new Map()
const active = new Set()

function literal(content) {
  if (content === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
  if (ERRS.has(content)) return err(content)
  return { k: 's', v: content }
}

function cellValue(key) {
  const c = cells.get(key)
  if (!c) return num(0)
  if (memo.has(key)) return memo.get(key)
  if (active.has(key)) return err('#CYCLE!')
  active.add(key)
  let v
  if (c.content[0] !== '=') v = literal(c.content)
  else if (!c.ast || c.ast.isBad) v = err('#ERR!')
  else v = ev(c.ast.e)
  active.delete(key)
  memo.set(key, v)
  return v
}

function asNum(v) {
  if (v.k === 'n') return v
  if (v.k === 'b') return num(v.v ? 1 : 0)
  if (v.k === 's') return err('#VALUE!')
  return v
}
const finite = (n) => (Number.isFinite(n) ? num(n) : err('#DIV/0!'))

const rank = { n: 0, s: 1, b: 2 }
function cpCompare(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
function compare(a, b) {
  if (a.k !== b.k) return rank[a.k] - rank[b.k]
  if (a.k === 's') return cpCompare(a.v, b.v)
  return Number(a.v) - Number(b.v)
}

function rangeCells(n) {
  const a = parseAddr(n.a), b = parseAddr(n.b)
  if (!a || !b) return null
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push(cellValue(keyOf(c, r)))
  return out
}

function scalar(n) {
  if (n.t !== 'range') return ev(n)
  const l = rangeCells(n)
  if (!l) return err('#REF!')
  if (l.length !== 1) return err('#ERR!')
  return l[0]
}

function values(args) {
  const out = []
  for (const a of args) {
    if (a.t === 'range') {
      const l = rangeCells(a)
      if (!l) out.push(err('#REF!'))
      else out.push(...l)
    } else out.push(ev(a))
  }
  return out
}

function ev(n) {
  switch (n.t) {
    case 'num': return num(n.v)
    case 'bool': return { k: 'b', v: n.v }
    case 'ref': {
      const a = parseAddr(n.w)
      return a ? cellValue(a.key) : err('#REF!')
    }
    case 'neg': {
      const v = asNum(ev(n.e))
      if (v.k === 'e') return v
      return num(n.op === '-' ? -v.v : v.v)
    }
    case 'bin': {
      const l = ev(n.l), r = ev(n.r)
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        if (l.k === 'e') return l
        if (r.k === 'e') return r
        const d = compare(l, r)
        const res = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
        return { k: 'b', v: res }
      }
      const a = asNum(l)
      if (a.k === 'e') return a
      const b = asNum(r)
      if (b.k === 'e') return b
      switch (n.op) {
        case '+': return finite(a.v + b.v)
        case '-': return finite(a.v - b.v)
        case '*': return finite(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
        case '^': return finite(Math.pow(a.v, b.v))
      }
      return err('#ERR!')
    }
    case 'range': return err('#ERR!')
    case 'call': return call(n)
  }
  return err('#ERR!')
}

function call(n) {
  const { name, args } = n
  if (!ARITY[name]) return err('#NAME?')
  if (name === 'IF') {
    const c = scalar(args[0])
    let t
    if (c.k === 'e') return c
    if (c.k === 'b') t = c.v
    else if (c.k === 'n') t = c.v !== 0
    else return err('#VALUE!')
    return scalar(t ? args[1] : args[2])
  }
  const vals = values(args)
  const e = vals.find((v) => v.k === 'e')
  if (e) return e
  if (name === 'COUNT') return num(vals.filter((v) => v.k === 'n').length)
  const nums = []
  for (const v of vals) {
    const x = asNum(v)
    if (x.k === 'e') return x
    nums.push(x.v)
  }
  switch (name) {
    case 'ABS':
      if (nums.length !== 1) return err('#ERR!')
      return num(Math.abs(nums[0]))
    case 'SUM': return finite(nums.reduce((a, b) => a + b, 0))
    case 'MIN': return num(Math.min(...nums))
    case 'MAX': return num(Math.max(...nums))
    case 'AVG': return finite(nums.reduce((a, b) => a + b, 0) / nums.length)
  }
  return err('#ERR!')
}

function show(v) {
  switch (v.k) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

const out = []
for (const c of [...cells.values()].sort(byPos)) {
  out.push(`${c.key}=${show(cellValue(c.key))}\n`)
}
process.stdout.write(out.join(''))
